INSERT INTO knowledge_project (id, owner_user_id, slug, title, summary, visibility, status, license, default_branch_name, published_at, created_at, updated_at, category, tags, verification, verification_note)
INSERT INTO project_member (project_id,user_id,role,created_at) SELECT project_id,'u-yu','owner',captured_at FROM _public_company_seed_additional ON CONFLICT DO NOTHING;
INSERT INTO knowledge_branch (id,project_id,name,owner_user_id,is_protected,status,version,created_at,updated_at) SELECT branch_id,project_id,'main',NULL,TRUE,'active',1,captured_at,captured_at FROM _public_company_seed_additional ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_commit (id,project_id,branch_id,parent_commit_id,author_user_id,message,ai_assisted,idempotency_key,change_summary,created_at) SELECT commit_id,project_id,branch_id,NULL,'u-yu','导入公开官网摘要（待核验）',FALSE,'seed:public-company:'||slug||':v1',jsonb_build_object('seed',true,'sourceType','official_website','evidenceState','needs_verification'),captured_at FROM _public_company_seed_additional ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_node (id,project_id,kind,created_by_user_id,created_at) SELECT folder_id,project_id,'folder','u-yu',captured_at FROM _public_company_seed_additional UNION ALL SELECT doc_id,project_id,'document','u-yu',captured_at FROM _public_company_seed_additional UNION ALL SELECT source_node_id,project_id,'source','u-yu',captured_at FROM _public_company_seed_additional ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_node_state (project_id,branch_id,node_id,parent_node_id,name,position,deleted_at,updated_at) SELECT project_id,branch_id,folder_id,NULL::TEXT,'公开资料',1,NULL::TIMESTAMPTZ,captured_at FROM _public_company_seed_additional UNION ALL SELECT project_id,branch_id,doc_id,folder_id,'产品范围与证据边界',1,NULL::TIMESTAMPTZ,captured_at FROM _public_company_seed_additional UNION ALL SELECT project_id,branch_id,source_node_id,NULL::TEXT,source_title,2,NULL::TIMESTAMPTZ,captured_at FROM _public_company_seed_additional ON CONFLICT (branch_id,node_id) DO NOTHING;
INSERT INTO document_revision (id,project_id,node_id,branch_id,commit_id,content,content_text,content_hash,created_by_user_id,created_at) SELECT 'revision-'||project_id||'-public-v1',project_id,doc_id,branch_id,commit_id,'{"type":"doc","content":[]}'::jsonb,summary||E'\n\n证据状态：needs_verification。来源是企业公开官网入口和人工摘要；未从摘要推断商业指标。',content_hash,'u-yu',captured_at FROM _public_company_seed_additional ON CONFLICT (id) DO NOTHING;
INSERT INTO content_attribution (id,project_id,node_id,block_id,origin_commit_id,last_touch_commit_id,contributor_user_id,active,created_at,updated_at) SELECT 'attr-'||project_id||'-public',project_id,doc_id,doc_id||':block:1',commit_id,commit_id,'u-yu',TRUE,captured_at,captured_at FROM _public_company_seed_additional ON CONFLICT DO NOTHING;
INSERT INTO company (id,name,kind,summary,tags,created_at,updated_at) SELECT company_id,company_name,'company',company_summary,tags,captured_at,captured_at FROM _public_company_seed_additional ON CONFLICT (id) DO NOTHING;
INSERT INTO report (id,company_id,title,status,current_version,created_at,updated_at) SELECT report_id,company_id,title,'draft',1,captured_at,captured_at FROM _public_company_seed_additional ON CONFLICT (id) DO NOTHING;
INSERT INTO report_section (id,report_id,parent_section_id,heading,anchor,level,position,content,evidence_state,updated_at) SELECT section_id,report_id,NULL,'公开摘要与证据边界','public-summary-evidence',1,1,snapshot||E'\n\n该段仅记录官网公开表述；商业数据、客户规模和效果结论需要独立来源。','needs_verification',captured_at FROM _public_company_seed_additional ON CONFLICT (id) DO NOTHING;
INSERT INTO source (id,report_id,title,kind,url,language,state,captured_at,content_hash,snapshot,evidence_state,metadata) SELECT source_id,report_id,source_title,'web',source_url,'zh','active',captured_at,content_hash,snapshot,'needs_verification',jsonb_build_object('sourceType','official_website','publisher',publisher,'capturedAt',captured_at,'licenseNote','公开官网页面；仅引用与研究相关的短摘要，遵守原站条款。','retrievalMode','curated_url_summary') FROM _public_company_seed_additional ON CONFLICT (id) DO NOTHING;
INSERT INTO source_chunk (id,source_id,parent_section_id,heading_path,position,page,start_offset,end_offset,text,contextual_prefix,content_hash) SELECT chunk_id,source_id,section_id,ARRAY['公开官网','产品范围']::TEXT[],1,NULL,0,char_length(snapshot),snapshot,'企业公开官网摘要；证据状态：needs_verification；不能据此推断商业指标。',content_hash FROM _public_company_seed_additional ON CONFLICT (id) DO NOTHING;
INSERT INTO citation (id,report_id,section_id,source_id,chunk_id,quote,evidence_state,created_at) SELECT 'citation-'||project_id||'-public',report_id,section_id,source_id,chunk_id,snapshot,'needs_verification',captured_at FROM _public_company_seed_additional ON CONFLICT (id) DO NOTHING;
INSERT INTO entity (id,report_id,kind,name,normalized_name,source_id,evidence_state,attributes,created_at) SELECT entity_id,report_id,'company',company_name,lower(company_name),source_id,'fact',jsonb_build_object('officialUrl',source_url,'sourceType','official_website'),captured_at FROM _public_company_seed_additional ON CONFLICT DO NOTHING;
INSERT INTO entity (id,report_id,kind,name,normalized_name,source_id,evidence_state,attributes,created_at) SELECT topic_entity_id,report_id,'industry',tags[1],lower(slug||'-topic'),source_id,'needs_verification',jsonb_build_object('officialUrl',source_url),captured_at FROM _public_company_seed_additional ON CONFLICT DO NOTHING;
INSERT INTO relation_edge (id,report_id,from_entity_id,to_entity_id,relation,source_id,evidence_state,created_at) SELECT 'edge-'||project_id||'-public-scope',report_id,entity_id,topic_entity_id,'官网自述产品范围',source_id,'fact',captured_at FROM _public_company_seed_additional ON CONFLICT (id) DO NOTHING;
INSERT INTO project_stats (project_id,unique_readers,updated_at) SELECT project_id,0,captured_at FROM _public_company_seed_additional ON CONFLICT (project_id) DO NOTHING;
