-- 第二批公开企业资料：仅导入可访问官网入口与保守摘要。
-- 022 已在生产执行，新增企业必须使用独立迁移，避免改写历史迁移校验和。
-- 不创建用户，不写入阅读、Star、评论或 MR 行为；统计从 0 开始。

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM platform_user WHERE id = 'u-yu' AND status = 'active') THEN
    RAISE EXCEPTION '公开首发数据需要现有 active 维护者 u-yu；拒绝创建虚构用户';
  END IF;
END $$;

CREATE TEMP TABLE _public_company_seed_additional (
  project_id TEXT PRIMARY KEY, slug TEXT NOT NULL, title TEXT NOT NULL, summary TEXT NOT NULL,
  tags TEXT[] NOT NULL, company_id TEXT NOT NULL, company_name TEXT NOT NULL, company_summary TEXT NOT NULL,
  report_id TEXT NOT NULL, branch_id TEXT NOT NULL, commit_id TEXT NOT NULL, folder_id TEXT NOT NULL,
  doc_id TEXT NOT NULL, source_node_id TEXT NOT NULL, section_id TEXT NOT NULL, source_id TEXT NOT NULL,
  chunk_id TEXT NOT NULL, entity_id TEXT NOT NULL, topic_entity_id TEXT NOT NULL,
  source_title TEXT NOT NULL, publisher TEXT NOT NULL, source_url TEXT NOT NULL, snapshot TEXT NOT NULL,
  content_hash TEXT NOT NULL, captured_at TIMESTAMPTZ NOT NULL
) ON COMMIT DROP;


SELECT project_id,'u-yu',slug,title,summary,'public','published','cc-by-4.0','main',captured_at,captured_at,captured_at,'企业',tags,'needs_verification','只包含官网公开入口与摘要；商业数据和效果结论仍待独立证据核验。' FROM _public_company_seed_additional ON CONFLICT (id) DO NOTHING;
UPDATE knowledge_branch b SET head_commit_id=s.commit_id,version=GREATEST(b.version,1),updated_at=s.captured_at FROM _public_company_seed_additional s WHERE b.id=s.branch_id;

